const input = $input.first()?.json || {};
const body = input.body || input;

let channel = body.channel || 'webchat';
let customerMessage = '';
let phoneNumber = '';
let telegramId = '';
let email = '';
let fullName = '';
let channelUserId = '';

// 1. Meta WhatsApp Webhook Detection
if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value?.messages) {
  channel = 'whatsapp';
  const val = body.entry[0].changes[0].value;
  const msg = val.messages[0];
  customerMessage = msg.text?.body || msg.interactive?.button_reply?.title || 'Hello';
  phoneNumber = '+' + msg.from;
  channelUserId = phoneNumber;
  fullName = val.contacts?.[0]?.profile?.name || 'WhatsApp User';
}

// 1b. Direct / Baileys / Evolution WhatsApp Ingress Detection
else if (body.channel === 'whatsapp' || (body.event === 'messages.upsert' && body.data?.message) || body.data?.key?.remoteJid) {
  channel = 'whatsapp';
  const data = body.data || body;
  const msg = data.message || {};
  customerMessage = body.customer_message || msg.conversation || msg.extendedTextMessage?.text || body.message || 'Hello';
  const rawPhone = (data.key?.remoteJid ? data.key.remoteJid.split('@')[0] : (body.phone_number || body.phone || ''));
  phoneNumber = rawPhone ? (rawPhone.startsWith('+') ? rawPhone : ('+' + rawPhone.replace(/[^0-9]/g, ''))) : '+966500000000';
  channelUserId = phoneNumber;
  fullName = body.full_name || data.pushName || 'WhatsApp Citizen';
}
// 2. Telegram Bot Webhook Detection
else if (body.message && body.message.chat) {
  channel = 'telegram';
  customerMessage = body.message.text || 'مرحبا';
  telegramId = String(body.message.from?.id || body.message.chat.id);
  channelUserId = telegramId;
  fullName = [body.message.from?.first_name, body.message.from?.last_name].filter(Boolean).join(' ') || body.message.from?.username || 'Telegram Citizen';
}
// 3. Email Ingress Detection
else if (body.from && (body.subject || body.body)) {
  channel = 'email';
  customerMessage = body.body || body.message || body.subject || '';
  email = body.from;
  channelUserId = email;
  fullName = body.name || email.split('@')[0];
}
// 4. Webchat / Direct REST API
else {
  customerMessage = body.customer_message || body.message || 'مرحبا، أود الاستفسار عن حالة طلبي SRV-1001';
  phoneNumber = body.phone || body.phone_number || '';
  telegramId = body.telegram_id || '';
  email = body.email || '';
  fullName = body.name || body.full_name || 'Valued Citizen';
  channelUserId = phoneNumber || telegramId || email || 'web-anon';
}

// 5. DEPI Compliance: PII Masking & Language Detection
let sanitizedMessage = customerMessage;
let piiDetected = false;

// Saudi National ID (10 digits starting with 1 or 2)
if (/\b[12]\d{9}\b/.test(sanitizedMessage)) {
  sanitizedMessage = sanitizedMessage.replace(/\b[12]\d{9}\b/g, '[NATIONAL_ID_MASKED]');
  piiDetected = true;
}

// Credit Card numbers
if (/\b(?:\d{4}[ -]?){3}\d{4}\b/.test(sanitizedMessage)) {
  sanitizedMessage = sanitizedMessage.replace(/\b(?:\d{4}[ -]?){3}\d{4}\b/g, '[CARD_MASKED]');
  piiDetected = true;
}

// Saudi IBANs
if (/\bSA\d{2}[0-9A-Z]{20}\b/i.test(sanitizedMessage)) {
  sanitizedMessage = sanitizedMessage.replace(/\bSA\d{2}[0-9A-Z]{20}\b/gi, '[IBAN_MASKED]');
  piiDetected = true;
}

// Language Detection (Arabic block)
const isArabic = /[\u0600-\u06FF]/.test(customerMessage);
const locale = isArabic ? 'ar' : 'en';

return [{
  json: {
    channel: channel,
    channel_user_id: channelUserId,
    customer_message: customerMessage,
    sanitized_message: sanitizedMessage,
    pii_detected: piiDetected,
    phone_number: phoneNumber,
    telegram_id: telegramId,
    email: email,
    full_name: fullName,
    locale: locale,
    start_time: Date.now()
  }
}];

const ai = $('Call SubWF 03 - AI Intent Engine').first()?.json.ai_output || {};
const norm = $('Channel Ingress & PII Sanitizer').first()?.json || {};
const isAr = norm.locale === 'ar';
const customerName = norm.full_name || '';

const welcomeAr = `أهلاً وسهلاً بك${customerName ? ' ' + customerName : ''} في منصة خدمة العملاء الذكية لمبادرة الرواد الرقميون (DEPI)! 🏛️

يسعدني مساعدتك. يمكنك الاستفسار عن أي من خدماتنا التالية:

📌 *مبادرة الرواد الرقميون (DEPI)* - برامج الماجستير والتدريب المهني
📝 *شروط التقديم والتسجيل* - الفئات المستهدفة والمستندات المطلوبة
🎓 *نظام الدراسة والامتحانات* - المنصة التعليمية والإجازات
🏆 *التخصصات المتاحة* - الذكاء الاصطناعي، الأمن السيبراني، وغيرها
⏱️ *الدعم الفني* - مساعدة واستفسارات

ما الذي تودّ الاستفسار عنه؟`;

const welcomeEn = `Welcome${customerName ? ' ' + customerName : ''} to the DEPI AI Customer Service Platform! 🏛️

I'm here to help. You can inquire about any of our services:

📌 *Digital Pioneers Initiative (DEPI)* - Master's & Professional Training
📝 *Admissions & Registration* - Eligibility & Required Documents
🎓 *Study & Exams System* - LMS & Attendance
🏆 *Available Tracks* - AI, Cybersecurity, etc.
⏱️ *Support* - Help & Inquiries

What would you like to know more about?`;

return [{
  json: {
    status: 'general',
    intent_handled: 'general_support',
    reply: ai.direct_response || (isAr ? welcomeAr : welcomeEn)
  }
}];

const handlerResult = $input.first()?.json || {};
const aiContext = $('Call SubWF 03 - AI Intent Engine').first()?.json || {};
const norm = $('Channel Ingress & PII Sanitizer').first()?.json || {};

const finalReply = handlerResult.reply || "Thank you for contacting customer service. How may we assist you?";
const latency = Date.now() - (norm.start_time || Date.now());

return [{
  json: {
    customer: aiContext.customer,
    conversation: aiContext.conversation,
    customer_message: norm.customer_message,
    sanitized_message: norm.sanitized_message,
    pii_detected: norm.pii_detected,
    channel: norm.channel,
    channel_user_id: norm.channel_user_id,
    locale: norm.locale,
    ai_output: aiContext.ai_output,
    handler_status: handlerResult.status,
    ticket_number: handlerResult.ticket_number || null,
    order_found: handlerResult.order_found || null,
    final_reply: finalReply,
    latency_ms: latency
  }
}];

const customer = $('Find or Upsert Customer').first()?.json || {};
const conv = $('Get or Start Conversation').first()?.json || {};
const trigger = $('Execute Workflow Trigger').first()?.json || {};
const history = conv.recent_history || [];

return [{
  json: {
    customer: customer,
    conversation: {
      id: conv.id,
      customer_id: conv.customer_id,
      channel: conv.channel,
      status: conv.status,
      language: conv.language,
      created_at: conv.created_at
    },
    conversation_history: history,
    customer_message: trigger.customer_message || '',
    sanitized_message: trigger.sanitized_message || trigger.customer_message || '',
    pii_detected: trigger.pii_detected || false,
    channel: trigger.channel || conv.channel || 'webchat',
    channel_user_id: trigger.channel_user_id || customer.phone_number || customer.telegram_id || 'anonymous',
    locale: trigger.locale || conv.language || customer.preferred_language || 'ar'
  }
}];

const input = $input.first()?.json || {};
const rawMsg = input.sanitized_message || input.customer_message || 'Hello';

// Enterprise Guardrails: Detect Prompt Injection and Harmful Input
const injectionPatterns = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions/i,
  /system\s*prompt/i,
  /jailbreak/i,
  /bypass\s+rules/i,
  /disregard\s+guidelines/i,
  /تجاهل\s+(كافة|جميع)?\s+التعليمات/i,
  /تخطي\s+الحماية/i
];

let promptInjection = false;
for (const pattern of injectionPatterns) {
  if (pattern.test(rawMsg)) {
    promptInjection = true;
    break;
  }
}

return [{
  json: {
    ...input,
    guardrail_safe: !promptInjection,
    flagged_reason: promptInjection ? 'prompt_injection_attempt' : null
  }
}];

const nodeInput = $input.first()?.json || {};
const buildData = $('Build Prompt Payload').first()?.json || {};

if (buildData.direct_bypass) {
  return [{
    json: {
      ai_output: buildData.ai_output,
      customer_message: buildData.customer_message,
      customer: buildData.customer,
      conversation: buildData.conversation,
      channel: buildData.channel,
      channel_user_id: buildData.channel_user_id,
      locale: buildData.locale
    }
  }];
}

const rawResponse = nodeInput.response;
const originalMsg = (buildData.customer_message || '').toLowerCase();
const locale = buildData.locale || 'ar';
const isAr = locale === 'ar';

let parsed = null;
try {
  if (rawResponse) {
    let cleanJson = rawResponse.replace(/```json/gi, '').replace(/```/g, '').trim();
    const match = cleanJson.match(/\{[\s\S]*\}/);
    if (match) cleanJson = match[0];
    parsed = JSON.parse(cleanJson);
  }
} catch (e) {
  parsed = null;
}

// Enterprise Heuristic Fail-Safe
if (!parsed || !parsed.intent) {
  const isOrder = originalMsg.includes('order') || originalMsg.includes('srv-') || originalMsg.includes('ord-') || originalMsg.includes('طلب') || originalMsg.includes('شحن') || originalMsg.includes('تتبع');
  const isEscalation = originalMsg.includes('human') || originalMsg.includes('supervisor') || originalMsg.includes('angry') || originalMsg.includes('موظف') || originalMsg.includes('مشرف') || originalMsg.includes('شكوى') || originalMsg.includes('إنسان');
  const isFaq = originalMsg.includes('skill') || originalMsg.includes('policy') || originalMsg.includes('hours') || originalMsg.includes('مهارات') || originalMsg.includes('ساعات') || originalMsg.includes('شروط') || originalMsg.includes('تقديم') || originalMsg.includes('خدمات') || originalMsg.includes('الخدمات') || originalMsg.includes('توقيع');

  if (isEscalation) {
    parsed = {
      intent: 'human_escalation',
      confidence: 0.95,
      entities: {},
      sentiment: 'frustrated',
      requires_human: true,
      direct_response: isAr ? 'يتم الآن تحويلك إلى ممثل خدمة العملاء المختص لمساعدتك...' : 'Connecting you with a human support specialist...'
    };
  } else if (isOrder) {
    const match = originalMsg.match(/(?:ord|srv)-\d+/i);
    parsed = {
      intent: 'order_lookup',
      confidence: 0.90,
      entities: { order_number: match ? match[0].toUpperCase() : 'SRV-1001' },
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري الاستعلام عن بيانات ومسار شحنتك/طلبك...' : 'Looking up your service request details...'
    };
  } else if (isFaq) {
    parsed = {
      intent: 'faq_query',
      confidence: 0.90,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري البحث في قاعدة المعرفة والخدمات المعتمدة...' : 'Searching the official knowledge base...'
    };
  } else {
    parsed = {
      intent: 'general_support',
      confidence: 0.85,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr
        ? 'أهلاً وسهلاً بك في منصة خدمة العملاء لمبادرة الرواد الرقميون (DEPI). كيف يمكننا خدمتك اليوم؟'
        : 'Welcome to the DEPI Customer Service platform. How may we assist you today?'
    };
  }
}

if (!parsed.entities) { parsed.entities = {}; }
if (!parsed.entities.order_number) {
  const match = originalMsg.match(/(?:ord|srv)-\d+/i);
  if (match) { parsed.entities.order_number = match[0].toUpperCase(); }
}

return [{
  json: {
    ai_output: parsed,
    customer_message: buildData.customer_message,
    customer: buildData.customer,
    conversation: buildData.conversation,
    channel: buildData.channel,
    channel_user_id: buildData.channel_user_id,
    locale: locale
  }
}];

const results = $input.first()?.json.results || [];
const inputData = $('Execute Workflow Trigger').first()?.json || {};
const locale = inputData.locale || 'ar';
const isAr = locale === 'ar';

const statusMapAr = {
  'shipped': 'تم الشحن والإرسال',
  'delivered': 'تم التسليم بنجاح',
  'processing': 'قيد المعالجة والتجهيز',
  'in_review': 'قيد المراجعة والتدقيق',
  'approved': 'تمت الموافقة المبدئية',
  'cancelled': 'ملغي'
};

if (results.length > 0 && results[0].order_number) {
  const order = results[0];
  const formattedDate = order.estimated_delivery ? new Date(order.estimated_delivery).toLocaleDateString(isAr ? 'ar-SA' : 'en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : (isAr ? 'قريباً' : 'soon');
  const statusText = isAr ? (statusMapAr[(order.status || '').toLowerCase()] || order.status) : (order.status || '').toUpperCase();

  let reply = '';
  if (isAr) {
    reply = `أهلاً بك ${order.full_name || 'عزيزنا العميل'}،\nحالة طلبك/طلب الخدمة رقم **${order.order_number}** هي: **${statusText}**.\n\n`;
    if (order.carrier && order.tracking_number) {
      reply += `📦 جهة التوصيل/الناقل: ${order.carrier}\n🔍 رقم التتبع: ${order.tracking_number}\n📅 تاريخ الوصول المتوقع: ${formattedDate}\n`;
    } else {
      reply += `يتم تجهيز طلبك حالياً، والتاريخ المتوقع للاكتمال: ${formattedDate}.\n`;
    }
    if (order.service_type) {
      reply += `📋 نوع الخدمة: ${order.service_type}\n`;
    }
    reply += `\nنسعد بخدمتك دائماً. هل لديك أي استفسار آخر؟`;
  } else {
    reply = `Hello ${order.full_name || 'there'},\nYour service request/order **${order.order_number}** is currently **${statusText}**.\n\n`;
    if (order.carrier && order.tracking_number) {
      reply += `📦 Carrier: ${order.carrier}\n🔍 Tracking Number: ${order.tracking_number}\n📅 Estimated Delivery: ${formattedDate}\n`;
    } else {
      reply += `We are processing your request. Estimated completion: ${formattedDate}.\n`;
    }
    if (order.service_type) {
      reply += `📋 Service Type: ${order.service_type}\n`;
    }
    reply += `\nTotal: ${order.total_amount} ${order.currency}. Please let us know if you need any additional support!`;
  }

  return [{
    json: {
      status: 'success',
      intent_handled: 'order_lookup',
      order_found: true,
      order_data: order,
      reply: reply
    }
  }];
} else {
  const requestedNum = inputData.ai_output?.entities?.order_number || inputData.entities?.order_number || (inputData.customer_message || '').match(/(?:ord|srv)-\d+/i)?.[0] || (isAr ? 'الطلب المحدد' : 'your requested order');
  const notFoundReply = isAr
    ? `لم نتمكن من العثور على طلب أو معاملة برقم "${requestedNum}". يرجى التأكد من صحة رقم الطلب (مثال: SRV-1001 أو ORD-1001) أو إرسال رقم الهوية/الجوال المسجل.`
    : `I could not find an active service request or order matching "${requestedNum}". Please verify the reference number (e.g. SRV-1001 or ORD-1001) or provide your registered contact details.`;

  return [{
    json: {
      status: 'not_found',
      intent_handled: 'order_lookup',
      order_found: false,
      reply: notFoundReply
    }
  }];
}

const results = ($input.first()?.json || []);
const rows = Array.isArray(results) ? results : (results.results || [results]);
const triggerData = $('Execute Workflow Trigger').first()?.json || {};
const locale = triggerData.locale || 'ar';
const isAr = locale === 'ar';
const customerMsg = triggerData.customer_message || triggerData.sanitized_message || '';

// Filter results with relevance > 0
const relevant = rows.filter(r => r && r.relevance_score > 0);

if (relevant.length > 0) {
  // Build context from top matching FAQ entries
  const contextParts = relevant.map(kb => {
    const q = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);
    const a = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
    return `سؤال: ${q}\nإجابة: ${a}`;
  });
  const context = contextParts.join('\n---\n');

  return [{
    json: {
      status: 'rag_context_found',
      intent_handled: 'faq_query',
      rag_context: context,
      customer_message: customerMsg,
      locale: locale,
      top_category: relevant[0].category,
      relevance_score: relevant[0].relevance_score
    }
  }];
} else {
  // No relevant FAQ found - will trigger guardrail
  return [{
    json: {
      status: 'no_context',
      intent_handled: 'faq_query',
      rag_context: '',
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0
    }
  }];
}

const ragData = $('Format RAG Knowledge Response').first()?.json || {};
const qwenOutput = $input.first()?.json || {};
const locale = ragData.locale || 'ar';
const isAr = locale === 'ar';

let finalReply = '';

if (ragData.status === 'no_context' || ragData.relevance_score === 0) {
  // Hard guardrail: no relevant FAQ found
  finalReply = isAr
    ? 'عذراً، هذا الاستفسار خارج نطاق خدماتنا المعتمدة حالياً.\n\nيسعدني مساعدتك في الاستفسار عن:\n📌 مبادرة الرواد الرقميون (DEPI)\n📝 شروط التقديم والتسجيل\n🎓 نظام الدراسة والامتحانات\n🏆 التخصصات المتاحة\n⏱️ الدعم الفني\n\nأو يمكنك طلب التحدث مع ممثل خدمة العملاء.'
    : 'Sorry, this inquiry is outside our current service scope.\n\nI can help you with:\n📌 Digital Pioneers Initiative (DEPI)\n📝 Admissions & Registration\n🎓 Study & Exams System\n🏆 Available Tracks\n⏱️ Support\n\nOr you may request to speak with a human specialist.';
} else {
  // Use Qwen's grounded response
  finalReply = qwenOutput.response || ragData.rag_context || '';

  // Clean up any markdown artifacts that don't render well in WhatsApp
  finalReply = finalReply.replace(/\*\*/g, '*').replace(/^#+\s*/gm, '').trim();
}

return [{
  json: {
    status: ragData.status === 'no_context' ? 'out_of_scope' : 'success',
    intent_handled: 'faq_query',
    category: ragData.top_category || 'general',
    reply: finalReply,
    sources: ragData.status === 'no_context' ? ['Guardrail: Out of Scope'] : ['DEPI Official Knowledge Base - ' + (ragData.top_category || 'General')]
  }
}];

