const ticket = $('Create SLA Ticket in Postgres').first()?.json || {};
const trigger = $('Execute Workflow Trigger').first()?.json || {};
const locale = trigger.locale || 'ar';
const isAr = locale === 'ar';
const ticketNum = ticket.ticket_number || 'TICK-NEW';
const priority = ticket.priority || 'high';

let reply = '';
if (isAr) {
  reply = `تم استلام طلبك وتصعيده إلى الفريق المختص. تم فتح تذكرة دعم ذات أولوية برقم **#${ticketNum}** (درجة الأولوية: ${priority === 'urgent' ? 'عاجلة' : 'عالية'}).\nيقوم أحد مسؤولي خدمة العملاء بمراجعة تفاصيل استفسارك حالياً وسيتواصل معك مباشرة.`;
} else {
  reply = `I understand this requires specialist attention. I have opened priority support ticket **#${ticketNum}** for you (Priority: ${priority.toUpperCase()}).\nA customer support representative has been assigned and is reviewing your request to assist you directly.`;
}

return [{
  json: {
    status: 'escalated',
    intent_handled: 'human_escalation',
    ticket_number: ticketNum,
    priority: priority,
    sla_due_at: ticket.sla_due_at,
    reply: reply
  }
}];

return [{
  json: {
    logged: true,
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first()?.json || {};
const recipient = item.phone_number || item.channel_user_id || item.customer?.phone_number || '+966501234567';
const text = item.reply || item.final_reply || item.message || '';

// Clean for WhatsApp: remove HTML, excessive newlines, fix markdown
let cleanText = text
  .replace(/<[^>]*>/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/\*\*/g, '*')
  .trim();

return [{
  json: {
    channel: 'whatsapp',
    recipient: recipient,
    dispatched: true,
    meta_payload: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: recipient.replace(/[^0-9]/g, ''),
      type: 'text',
      text: { body: cleanText }
    },
    message: cleanText,
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first()?.json || {};
const chatId = item.channel_user_id || item.customer?.telegram_id || '987654321';
const text = item.reply || item.message || '';

return [{
  json: {
    channel: 'telegram',
    recipient: chatId,
    dispatched: true,
    meta_payload: {
      chat_id: chatId,
      text: text,
      parse_mode: 'Markdown'
    },
    message: text,
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first()?.json || {};
const email = item.customer?.email || item.email || 'citizen@example.gov.sa';
const text = item.reply || item.message || '';

return [{
  json: {
    channel: 'email',
    recipient: email,
    dispatched: true,
    meta_payload: {
      to: email,
      subject: 'DEPI Citizen Customer Service Notification',
      body: text
    },
    message: text,
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first()?.json || {};
const text = item.reply || item.message || '';

return [{
  json: {
    channel: 'webchat',
    recipient: item.customer?.id || 'web-session',
    dispatched: true,
    meta_payload: {
      session_id: item.session_id || item.conversation?.id,
      response: text
    },
    message: text,
    timestamp: new Date().toISOString()
  }
}];
